class Solution:
    def subarraySum(self, nums: list[int]) -> int:
        from itertools import accumulate
        pref = list(accumulate(nums, initial=0))
        ans = 0
        for i, x in enumerate(nums):
            start = max(0, i - x)
            ans += pref[i + 1] - pref[start]
        return ans

#include <vector>
#include <algorithm>

class Solution {
public:
    int subarraySum(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            pref[i + 1] = pref[i] + nums[i];
        }
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            int start = std::max(0, i - nums[i]);
            ans += pref[i + 1] - pref[start];
        }
        return ans;
    }
};

class Solution {
    public int subarraySum(int[] nums) {
        int n = nums.length;
        int[] pref = new int[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + nums[i];
        }
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int start = Math.max(0, i - nums[i]);
            ans += pref[i + 1] - pref[start];
        }
        return ans;
    }
}

